import{getWrapper as t,postWrapper as e}from"fetch";import{$submitBtn as o}from"loading";import{createToast as n}from"toast";export const $contactBtn=document.getElementById("contactBtn");export async function getContactForm(){return t({url:"/contact",$loadingDiv:null,loading:"",dataHandler:t=>{let a=document.createElement("div");a.innerHTML=t,document.getElementById("loadedModal").appendChild(a),globalModals.$contactFormModal=new bootstrap.Modal(document.getElementById("contactFormModal"),{});let c=document.getElementById("contactForm"),d=document.getElementById("submitContactForm");d.addEventListener("click",async t=>{let a=c.checkValidity();if(c.classList.add("was-validated"),!a)return t.preventDefault(),void t.stopPropagation();document.getElementById("closeContactForm").disabled=!0;let l=new FormData(c),r=Object.fromEntries(l.entries());await async function submitContactForm(t,a){return e({url:"/home/contact",$loadingBtn:a,loading:o,packet:JSON.stringify(t),responseType:"json",dataHandler:()=>{globalModals.$contactFormModal.hide(),n("Email sent! Thanks for contacting us!","success","bi-check-square-fill")}})}(r,d)})}})}